#include "common/benchmark.hpp"
#include "cfd/particle/electromagnetic.hpp"
#include <vector>
int main(int argc,char**argv){using namespace cfd::examples;const auto o=parse_options(argc,argv);const std::size_t grid=o.quick?32U:256U*o.scale,particles_n=o.quick?64U:4000U*o.scale,steps=o.quick?3U:80U;Timer setup;cfd::particle::ElectromagneticPic1DConfig cfg;cfg.grid_points=grid;cfg.length_m=1.0;cfg.solve_longitudinal_poisson=true;cfg.dt_s=0.15*(1.0/double(grid))/299792458.0;cfd::particle::ElectromagneticPic1D pic(cfg);std::vector<cfd::particle::ChargedParticle> p(particles_n);for(std::size_t i=0;i<particles_n;++i){auto&x=p[i];x.mass_kg=9.1093837139e-31;x.charge_c=(i&1U)?1.0e-20:-1.0e-20;x.weight=1.0;x.position_m={double(i)/double(particles_n),0,0};x.velocity_m_per_s={1e5,((i&1U)?1.0:-1.0)*2e4,0};}pic.set_particles(std::move(p));pic.initialize_right_traveling_mode(1.0,1U);const double setup_ms=setup.milliseconds();Timer sim;pic.step(steps);const double sim_ms=sim.milliseconds();const auto d=pic.diagnostics();emit({"phase12_em_pic","periodic_em_pic_beam","cpu","particle_steps",particles_n,steps,setup_ms,sim_ms,double(particles_n)*double(steps),d.total_energy_j+d.charge_continuity_linf_residual});return 0;}
